"C:\\Users\\flavi\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -Command '$checks=@{
  '"'runtime_normalizes'=(Select-String -LiteralPath apps/api/src/operations/operations-runtime.service.ts -Pattern 'const idempotencyKey = input.idempotencyKey.trim' -Quiet)
  'stores_normalize'=((Select-String -LiteralPath packages/jobs/src/index.ts -Pattern 'const idempotencyKey = input.idempotencyKey.trim' | Measure-Object).Count -ge 2)
  'cursor_guard'=(Select-String -LiteralPath packages/jobs/src/index.ts -Pattern 'Operation repository cursor repeated' -Quiet)
  'normalization_test'=(Select-String -LiteralPath packages/jobs/tests/jobs.test.ts -Pattern 'whitespace outside' -Quiet)
}; "'$checks.GetEnumerator() | ForEach-Object { "$($_.Key)=$($_.Value)" }; Write-Output "node=$(node --version) pnpm=$(pnpm --version)"; Write-Output "lockfile_sha256=$((Get-FileHash -Algorithm SHA256 pnpm-lock.yaml).Hash)"; Write-Output "tsc=$(Test-Path node_modules/.bin/tsc.cmd) vitest=$(Test-Path node_modules/.bin/vitest.cmd) prettier=$(Test-Path node_modules/.bin/prettier.cmd)"'

